SELECT a.id_asignatura, a.nombre, a.carga_horaria, a.id_departamento
FROM asignaturas a
WHERE a.carga_horaria > (
        SELECT AVG(a2.carga_horaria)
        FROM asignaturas a2
        WHERE a2.id_departamento = a.id_departamento
      )
  AND a.id_departamento IN (
        SELECT id_departamento FROM carreras WHERE nivel = 'grado'
      );

SELECT a.id_alumno, a.nombre, a.apellido, a.email, a.telefono
FROM alumnos a
WHERE a.telefono IS NULL;

SELECT a.id_asignatura, a.nombre AS asignatura, a.id_departamento
FROM asignaturas a
WHERE a.id_departamento IN (
  SELECT d.id_departamento
  FROM departamentos d
  WHERE d.presupuesto > (
    SELECT AVG(d2.presupuesto)
    FROM departamentos d2
  )
);

SELECT a.id_alumno, a.nombre, a.apellido
FROM alumnos a
WHERE a.id_alumno NOT IN (
  SELECT ac.id_alumno
  FROM alumno_carrera ac
);
